def periodic_points(step, states, n):
    """Enumerate n-periodic points of a finite dynamical system."""
    result = set()
    for x in states:
        y = x
        for _ in range(n):
            y = step[y]
        if y == x:
            result.add(x)
    return result

# Example
step = {0: 1, 1: 2, 2: 0, 3: 4, 4: 3, 5: 5}
for n in range(7):
    pts = periodic_points(step, range(6), n)
    print(f'Per_{n} = {sorted(pts)}')

def trace_periodic_count(step, states, n):
    """Compute periodic point count via the trace formula tr(A^n)."""
    k = len(states)
    idx = {s: i for i, s in enumerate(states)}
    # Build transition matrix
    A = [[0]*k for _ in range(k)]
    for i, s in enumerate(states):
        A[i][idx[step[s]]] = 1
    # Matrix power by repeated squaring
    def mat_mul(X, Y):
        return [[sum(X[i][l]*Y[l][j] for l in range(k)) for j in range(k)] for i in range(k)]
    result = [[int(i==j) for j in range(k)] for i in range(k)]
    base = [row[:] for row in A]
    m = n
    while m > 0:
        if m % 2: result = mat_mul(result, base)
        base = mat_mul(base, base)
        m //= 2
    return sum(result[i][i] for i in range(k))

step = {0: 1, 1: 2, 2: 0, 3: 4, 4: 3, 5: 5}
for n in range(8):
    print(f'tr(A^{n}) = {trace_periodic_count(step, list(range(6)), n)}')

def find_eventual_period(step, states, max_n=50):
    """Find the eventual period of the periodic count sequence."""
    def iterate(x, n):
        for _ in range(n): x = step[x]
        return x
    counts = [sum(1 for x in states if iterate(x, n) == x) for n in range(max_n)]
    for p in range(1, max_n // 2):
        for N in range(max_n // 3):
            if all(counts[n] == counts[n+p] for n in range(N, max_n - p)):
                return N, p, counts
    return None, None, counts

step = {0: 3, 1: 5, 2: 0, 3: 1, 4: 2, 5: 4, 6: 6, 7: 3}
N, p, counts = find_eventual_period(step, list(range(8)))
print(f'Eventual period p={p} starting at N={N}')
print(f'First 20 counts: {counts[:20]}')
